// P12 로컬 골격: STORAGE-DESIGN 6.1 계약만 검사한다.
// 물리 저장소가 합의·연결되기 전에는 성공 StateRef를 만들거나 상태를 변경하지 않는다.
const input = $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v) => typeof v === 'string' && v.trim().length > 0;
const isStateRef = (v) => isObj(v) && isText(v.scope) && isText(v.request_id) && isText(v.owner_id) && isText(v.input_hash) && isText(v.execution_id) && Number.isInteger(v.state_revision) && v.state_revision >= 0;
const requestId = isObj(input.state_ref) && isText(input.state_ref.request_id) ? input.state_ref.request_id : (isObj(input.request) && isText(input.request.request_id) ? input.request.request_id : null);

if (!isObj(input) || !isText(input.op)) {
  return [{ json: { request_id: requestId, ok: false, skipped: false, state_ref: null, error_code: 'invalid_state_request' } }];
}

if (input.op === 'begin') {
  const valid = isText(input.scope) && isText(input.execution_id) && isText(input.input_hash) && isObj(input.actor) && isText(input.actor.id) && isObj(input.request) && isText(input.request.request_id);
  return [{ json: {
    request_id: requestId,
    mode: 'error',
    state_ref: null,
    support: null,
    facts: null,
    response: null,
    http_status: valid ? 503 : 400,
    error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request'
  } }];
}

if (input.op === 'save') {
  const valid = isStateRef(input.state_ref) && isText(input.case_id) && isText(input.first_request_id) && Number.isInteger(input.attempt) && input.attempt >= 1 && isText(input.ticket_id) && isObj(input.response);
  return [{ json: {
    request_id: requestId,
    ok: false,
    state_ref: null,
    error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request',
    recovery: { version: 1, mode: 'manual_required', action: 'finish', args: null, reference: null, reason: valid ? '물리 저장소 미연결' : '저장 요청 계약 오류' }
  } }];
}

const allowed = new Set(['prepare', 'bind', 'finish', 'fail']);
const valid = allowed.has(input.op) && isStateRef(input.state_ref) && isObj(input.args);
return [{ json: {
  request_id: requestId,
  ok: false,
  skipped: false,
  state_ref: null,
  error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request'
} }];
